package com.gymflow.category;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/gyms/{gymId}/categories")public class CategoryController{private final CategoryService service;public CategoryController(CategoryService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public CategoryResponse create(@PathVariable UUID gymId,@Valid @RequestBody CategoryRequest r){return service.create(gymId,r);}@GetMapping public List<CategoryResponse> findAll(@PathVariable UUID gymId){return service.findAll(gymId);}}
